import { HttpResponse, http } from 'msw';

import { env } from '@/config/env';

import { db, persistDb } from '../db';
import { networkDelay, requireAuth, sanitizeUser } from '../utils';

type CreateCommentBody = {
  body: string;
  discussionId: string;
};

export const commentsHandlers = [
  http.get(`${env.API_URL}/comments`, async ({ request, cookies }) => {
    await networkDelay();

    try {
      const { error } = requireAuth(cookies);
      if (error) {
        return HttpResponse.json({ message: error }, { status: 401 });
      }
      const url = new URL(request.url);
      const discussionId = url.searchParams.get('discussionId') || '';
      const page = Number(url.searchParams.get('page') || 1);

      const total = db.comment.count({
        where: {
          discussionId: {
            equals: discussionId,
          },
        },
      });

      const totalPages = Math.ceil(total / 10);

      const comments = db.comment
        .findMany({
          where: {
            discussionId: {
              equals: discussionId,
            },
          },
          take: 10,
          skip: 10 * (page - 1),
        })
        .map(({ authorId, ...comment }) => {
          const author = db.user.findFirst({
            where: {
              id: {
                equals: authorId,
              },
            },
          });
          return {
            ...comment,
            author: author ? sanitizeUser(author) : {},
          };
        });
      return HttpResponse.json({
        data: comments,
        meta: {
          page,
          total,
          totalPages,
        },
      });
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),

  http.post(`${env.API_URL}/comments`, async ({ request, cookies }) => {
    await networkDelay();

    try {
      const { user, error } = requireAuth(cookies);
      if (error) {
        return HttpResponse.json({ message: error }, { status: 401 });
      }
      const data = (await request.json()) as CreateCommentBody;
      const result = db.comment.create({
        authorId: user?.id,
        ...data,
      });
      await persistDb('comment');
      return HttpResponse.json(result);
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),

  http.delete(
    `${env.API_URL}/comments/:commentId`,
    async ({ params, cookies }) => {
      await networkDelay();

      try {
        const { user, error } = requireAuth(cookies);
        if (error) {
          return HttpResponse.json({ message: error }, { status: 401 });
        }
        const commentId = params.commentId as string;
        const result = db.comment.delete({
          where: {
            id: {
              equals: commentId,
            },
            ...(user?.role === 'USER' && {
              authorId: {
                equals: user.id,
              },
            }),
          },
        });
        await persistDb('comment');
        return HttpResponse.json(result);
      } catch (error: any) {
        return HttpResponse.json(
          { message: error?.message || 'Server Error' },
          { status: 500 },
        );
      }
    },
  ),

  http.patch(
    `${env.API_URL}/comments/:commentId`,
    async ({ params, request, cookies }) => {
      await networkDelay();
      try {
        const { user, error } = requireAuth(cookies);
        if (error) {
          return HttpResponse.json({ message: error }, { status: 401 });
        }
        const commentId = params.commentId as string;
        const data = (await request.json()) as { body: string };

        const comment = db.comment.findFirst({
          where: {
            id: { equals: commentId },
          },
        });

        if (user?.role !== 'ADMIN' && comment?.authorId !== user?.id) {
          return HttpResponse.json(
            { message: 'Unauthorized' },
            { status: 403 },
          );
        }

        if (!comment) {
          return HttpResponse.json(
            { message: 'Comment not found' },
            { status: 404 },
          );
        }

        const result = db.comment.update({
          where: { id: { equals: commentId } },
          data,
        });
        await persistDb('comment');
        return HttpResponse.json(result);
      } catch (error: any) {
        return HttpResponse.json(
          { message: error?.message || 'Server Error' },
          { status: 500 },
        );
      }
    },
  ),
];

import { ArchiveX } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { MDPreview } from '@/components/ui/md-preview';
import { Spinner } from '@/components/ui/spinner';
import { useUser } from '@/lib/auth';
import { POLICIES, Authorization } from '@/lib/authorization';
import { User } from '@/types/api';
import { formatDate } from '@/utils/format';

import { useInfiniteComments } from '../api/get-comments';

import { DeleteComment } from './delete-comment';
import { EditComment } from './edit-comment';

type CommentsListProps = {
  discussionId: string;
};

export const CommentsList = ({ discussionId }: CommentsListProps) => {
  const user = useUser();
  const commentsQuery = useInfiniteComments({ discussionId });

  if (commentsQuery.isLoading) {
    return (
      <div className="flex h-48 w-full items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  const comments = commentsQuery.data?.pages.flatMap((page) => page.data);

  if (!comments?.length)
    return (
      <div
        role="list"
        aria-label="comments"
        className="flex h-40 flex-col items-center justify-center bg-white text-gray-500"
      >
        <ArchiveX className="size-10" />
        <h4>No Comments Found</h4>
      </div>
    );

  return (
    <>
      <ul aria-label="comments" className="flex flex-col space-y-3">
        {comments.map((comment, index) => (
          <li
            aria-label={`comment-${comment.body}-${index}`}
            key={comment.id || index}
            className="w-full bg-white p-4 shadow-sm"
          >
            <div className="flex justify-between">
              <div>
                <span className="text-xs font-semibold">
                  {formatDate(comment.createdAt)}
                </span>
                {comment.author && (
                  <span className="text-xs font-bold">
                    {' '}
                    by {comment.author.firstName} {comment.author.lastName}
                  </span>
                )}
              </div>
              <div className="flex gap-2">
                <Authorization
                  policyCheck={POLICIES['comment:delete'](
                    user.data as User,
                    comment,
                  )}
                >
                  <DeleteComment discussionId={discussionId} id={comment.id} />
                </Authorization>
                {user.data && user.data.id === comment.author?.id && (
                  <EditComment discussionId={discussionId} id={comment.id} />
                )}
              </div>
            </div>

            <MDPreview value={comment.body} />
          </li>
        ))}
      </ul>
      {commentsQuery.hasNextPage && (
        <div className="flex items-center justify-center py-4">
          <Button onClick={() => commentsQuery.fetchNextPage()}>
            {commentsQuery.isFetchingNextPage ? (
              <Spinner />
            ) : (
              'Load More Comments'
            )}
          </Button>
        </div>
      )}
    </>
  );
};

Here are the changes to implement the "Edit Comment" feature:

### 1. API Hook (`src/features/comments/api/update-comment.ts`)
Added a new mutation hook and schema for updating comments, handling success notifications directly within the hook to follow the project's architecture rules.
```typescript
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { z } from 'zod';

import { api } from '@/lib/api-client';
import { useNotifications } from '@/components/ui/notifications';
import { MutationConfig } from '@/lib/react-query';

import { getInfiniteCommentsQueryOptions } from './get-comments';

export const updateCommentInputSchema = z.object({
  body: z.string().min(1, 'Required'),
});

export type UpdateCommentInput = z.infer<typeof updateCommentInputSchema>;

export const updateComment = ({
  commentId,
  data,
}: {
  commentId: string;
  data: UpdateCommentInput;
}): Promise<any> => {
  return api.patch(`/comments/${commentId}`, data);
};

type UseUpdateCommentOptions = {
  discussionId: string;
  mutationConfig?: MutationConfig<typeof updateComment>;
};

export const useUpdateComment = ({
  mutationConfig,
  discussionId,
}: UseUpdateCommentOptions) => {
  const queryClient = useQueryClient();
  const { addNotification } = useNotifications();

  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    onSuccess: (...args) => {
      addNotification({ type: 'success', title: 'Comment Updated' });
      queryClient.invalidateQueries({
        queryKey: getInfiniteCommentsQueryOptions(discussionId).queryKey,
      });
      onSuccess?.(...args);
    },
    ...restConfig,
    mutationFn: updateComment,
  });
};
```

### 2. Edit Component (`src/features/comments/components/edit-comment.tsx`)
Created a new component that wraps an edit form inside a `FormDrawer`. It renders only when the logged-in user is the original author of the comment.
```typescript
import { Pencil } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Form, FormDrawer, Textarea } from '@/components/ui/form';

import {
  useUpdateComment,
  updateCommentInputSchema,
} from '../api/update-comment';

type EditCommentProps = {
  discussionId: string;
  id: string;
};

export const EditComment = ({ discussionId, id }: EditCommentProps) => {
  const updateCommentMutation = useUpdateComment({
    discussionId,
  });

  return (
    <FormDrawer
      isDone={updateCommentMutation.isSuccess}
      triggerButton={
        <Button variant="outline" size="sm" icon={<Pencil className="size-4" />}>
          Edit
        </Button>
      }
      title="Edit Comment"
      submitButton={
        <Button
          isLoading={updateCommentMutation.isPending}
          form="edit-comment"
          type="submit"
          size="sm"
          disabled={updateCommentMutation.isPending}
        >
          Update
        </Button>
      }
    >
      <Form
        id="edit-comment"
        onSubmit={(values) => {
          updateCommentMutation.mutate({
            commentId: id,
            data: values,
          });
        }}
        schema={updateCommentInputSchema}
        options={{
          defaultValues: {
            body: '',
          },
        }}
      >
        {({ register, formState }) => (
          <Textarea
            label="Body"
            error={formState.errors['body']}
            registration={register('body')}
          />
        )}
      </Form>
    </FormDrawer>
  );
};
```

