        // Only allow author or admin to edit
        if (user?.role !== 'ADMIN' && comment?.authorId !== user?.id) {
          return HttpResponse.json({ message: 'Unauthorized' }, { status: 403 });
        }
        if (!comment) {
          return HttpResponse.json({ message: 'Comment not found' }, { status: 404 });
        }

        const result = db.comment.update({
          where: { id: { equals: commentId } },
          data,
        });
        await persistDb('comment');
        return HttpResponse.json(result);
      } catch (error: any) {
        return HttpResponse.json({ message: error?.message || 'Server Error' }, { status: 500 });
      }
    },
